package api.trash_p; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.util.List; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class TrashControllerTest { @Mock TrashService service; @InjectMocks TrashController controller; @Test @DisplayName("UT-BE-TRASH-CTRL-001 유형별 지난 기록을 조회한다") void list(){ List<TrashDTO>x=List.of(); when(service.list("BILL")).thenReturn(x); assertThat(controller.list("BILL")).isSameAs(x); } @Test @DisplayName("UT-BE-TRASH-CTRL-002 지난 기록 상세를 조회한다") void detail(){ TrashDTO x=new TrashDTO(); when(service.detail(1)).thenReturn(x); assertThat(controller.detail(1)).isSameAs(x); } @Test @DisplayName("UT-BE-TRASH-CTRL-003 지난 기록을 복원한다") void restore(){ TrashDTO x=new TrashDTO(); when(service.restore(1)).thenReturn(x); assertThat(controller.restore(1)).isSameAs(x); } @Test @DisplayName("UT-BE-TRASH-CTRL-004 차량번호로 지난 기록을 검색한다") void search(){ List<TrashDTO>x=List.of(); when(service.searchByCarNo("3456")).thenReturn(x); assertThat(controller.search("3456")).isSameAs(x); } }
